commands.command_text:
cd src/ledger/adapters && python - <<'EOF'
import ast, glob
for f in sorted(glob.glob("*.py")):
    if f == "__init__.py": continue
    t = ast.parse(open(f, encoding="utf-8").read())
    classes = {n.name: [ast.unparse(b) for b in n.bases] for n in t.body if isinstance(n, ast.ClassDef)}
    exc = [f"{k}({','.join(v)})" for k, v in classes.items() if any(b.endswith(("Error","Exception","Declined")) or b in ("RuntimeError","ValueError") for b in v)]
    cur = [ast.literal_eval(n.value) for n in t.body if isinstance(n, ast.Assign) and any(getattr(x,'id',None)=="SUPPORTED_CURRENCIES" for x in n.targets)]
    # minimum_charge table keys
    mc = None
    for n in t.body:
        if isinstance(n, ast.FunctionDef) and n.name == "minimum_charge":
            for s in ast.walk(n):
                if isinstance(s, ast.Dict): mc = [k.value for k in s.keys]
    print(f, "|", exc, "|", cur[0] if cur else None, "|", "min-table" , mc if mc != (cur[0] if cur else None) and mc != list(cur[0] if cur else []) else "same")
EOF
